static void hgics_rx_bt_data(struct hgics_wdev *hg, u8 *data, int len)
{
#ifndef __RTOS__
    struct hgic_ctrl_hdr *hdr = (struct hgic_ctrl_hdr *)data;

    if ((u16)(hg->rx_cookie + 1) != hdr->hdr.cookie) {
        hgic_err("cookie:%d-%d\r\n", hg->rx_cookie, hdr->hdr.cookie);
    }
    hg->rx_cookie = hdr->hdr.cookie;

#ifdef CONFIG_BT
    if (hg->hci) {
		data += sizeof(struct hgic_ctrl_hdr);
		len  -= sizeof(struct hgic_ctrl_hdr);
        hci_recv_fragment(hg->hci, hdr->hci.type, data, len);
    } else
#endif
    {
        struct sk_buff *skb = dev_alloc_skb(len);
        if (skb) {
            memcpy(skb->data, data, len);
            skb_put(skb, len);
            if (skb_queue_len(&hg->evt_list) > 16) {
                kfree_skb(skb_dequeue(&hg->evt_list));
            }
            skb_queue_tail(&hg->evt_list, skb);
            up(&hg->evt_sema);
        } else {
            hgic_err("alloc skb fail, drop bt data ...\r\n");
        }
    }
#else
    /* TBD... */
#endif
}

void hgics_rx_error(void *hgobj)
{
    struct hgics_wdev *hg = hgobj;

    hgic_fwctrl_rx_error(&hg->ctrl);
}

int hgics_rx_data(void *hgobj, u8 *data, int len)
{
    int i = 0;
    struct hgics_wdev *hg = hgobj;
    struct hgic_frm_hdr *hdr = NULL;
    struct hgic_dack_hdr *ackhdr = NULL;
    struct hgics_txstatus txstat;
    u16 magic, declared;
    int actual = len;

    if (READ_ONCE(hg->bus->rx_failed))
        return -EPROTO;
    if (!data || len < sizeof(struct hgic_hdr))
        goto bad_rx;
    /* Retail alignment prefix is at most four0xff bytes; bound the
     * helper's otherwise unbounded lookahead before parsing any header.
     */
    for (i = 0; i < 4 && i < len && data[i] == 0xff; i++) {}
    if (len - i < sizeof(struct hgic_hdr))
        goto bad_rx;
    data += i; len -= i;
    hdr = (struct hgic_frm_hdr *)data;
    magic = get_unaligned_le16(data);
    declared = get_unaligned_le16(data + 4);
    /* Qualification policy: one exact CMD/CMD2/EVENT/EVENT2 per USB completion.
     * No RX padding/prefix grammar is established for station control. Do not
     * borrow TX alignment rules, trim surplus (even zero), or flatten packets.
     * All checks precede wire normalization and the asynchronous A1 decoder.
     */
    if (magic != HGIC_HDR_RX_MAGIC || declared < sizeof(struct hgic_hdr))
        goto bad_rx;
    if ((hdr->hdr.type == HGIC_HDR_TYPE_CMD || hdr->hdr.type == HGIC_HDR_TYPE_CMD2 ||
         hdr->hdr.type == HGIC_HDR_TYPE_EVENT || hdr->hdr.type == HGIC_HDR_TYPE_EVENT2) &&
        (i != 0 || len < sizeof(struct hgic_ctrl_hdr) || declared != actual))
        goto bad_rx;
    if (hdr->hdr.type != HGIC_HDR_TYPE_BOOTDL && len < declared)
        goto bad_rx;
    hdr->hdr.magic  = le16_to_cpu(hdr->hdr.magic);
    hdr->hdr.length = le16_to_cpu(hdr->hdr.length);
    hdr->hdr.cookie = le16_to_cpu(hdr->hdr.cookie);

    if (hdr->hdr.magic != HGIC_HDR_RX_MAGIC) {
        hgic_err("invalid rx magic: %x\r\n", hdr->hdr.magic);
        return -1;
    }

    if (hdr->hdr.type != HGIC_HDR_TYPE_BOOTDL && len < hdr->hdr.length) {
        hgic_err("invalid data length: %x/%x, type:%d\r\n", len, hdr->hdr.length, hdr->hdr.type);
        return -1;
    }

    len = (len < hdr->hdr.length ? len : hdr->hdr.length);
    switch (hdr->hdr.type) {
        case HGIC_HDR_TYPE_ACK:
            hg->last_rx = jiffies;
            if (!test_bit(HGICS_STATE_START, &hg->state) || hg->if_test) {
                return -1;
            }
            ackhdr = (struct hgic_dack_hdr *)data;
            for (i = 0; i < (len - sizeof(*ackhdr)) / sizeof(ackhdr->cookies[0]) &&
                        i < HGIC_BLOCK_ACK_CNT; i++) {
                memset(&txstat, 0, sizeof(txstat));
                txstat.cookie = le16_to_cpu(ackhdr->cookies[i]) & HGIC_TX_COOKIE_MASK;
                txstat.acked  = (le16_to_cpu(ackhdr->cookies[i]) & 0x8000) ? 1 : 0;
                hgics_rx_ack(hg, &txstat);
            }
            break;
        case HGIC_HDR_TYPE_FRM:
        case HGIC_HDR_TYPE_AGGFRM:
            hg->last_rx = jiffies;
            if (!test_bit(HGICS_STATE_START, &hg->state) || hg->if_test) {
                return -1;
            }
            if (hdr->hdr.type == HGIC_HDR_TYPE_AGGFRM) {
                hgics_rx_agg_frm(hg, data, len);
            } else {
                hgics_rx_sigfrm(hg, data, len);
            }
            break;
        case HGIC_HDR_TYPE_CMD:
        case HGIC_HDR_TYPE_CMD2:
        case HGIC_HDR_TYPE_EVENT:
        case HGIC_HDR_TYPE_EVENT2:
        case HGIC_HDR_TYPE_BOOTDL:
        case HGIC_HDR_TYPE_OTA:
            hgic_fwctrl_rx(&hg->ctrl, data, len);
            break;
        case HGIC_HDR_TYPE_TEST2:
            hg->last_rx = jiffies;
            hg->test_rx_len += len;
            if (hg->if_test == 3) {
                for (i = 8; i < 1500; i++) {
                    if (data[i] != 0xAA) {
                        printk("data verify fail\r\n");
                        break;
                    }
                }
            }
            break;
        case HGIC_HDR_TYPE_SOFTFC:
            hg->last_rx = jiffies;
            atomic_set(&hg->txwnd, hdr->hdr.cookie);
            complete(&hg->txwnd_cp);
            break;
        case HGIC_HDR_TYPE_BLUETOOTH:
            if (!test_bit(HGICS_STATE_INITED, &hg->state) || hg->if_test) {
                return -1;
            }
            hgics_rx_bt_data(hg, data, len);
            break;
        default:
            hgic_err("unknow packet type:%d, len:%d, cookie:%x\n", hdr->hdr.type, len, hdr->hdr.cookie);
            return -1;
    }
    return 0;
bad_rx:
    hgics_rx_error(hg);
    return -EPROTO;
}

#include "hgics.h"
#include "event.h"

#include "../utils/control_receipt.h"

static_assert(sizeof(struct hgic_hdr) == 8, "selected outer ABI");
static_assert(sizeof(struct hgic_ctrl_hdr) == 12, "selected event ABI");
static_assert(offsetof(struct hgic_ctrl_hdr, event.event_id) == 8, "selected EVENT ID");
static_assert(offsetof(struct hgic_ctrl_hdr, event2.event_id) == 8, "selected EVENT2 ID");
static_assert(offsetof(struct hgic_ctrl_hdr, event.value) == 10, "selected EVENT value");
static_assert(offsetof(struct hgic_ctrl_hdr, event2.value) == 10, "selected EVENT2 value");

void hgics_rx_fw_event(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    u16 evt_id;

    /* Live ctrl/bus is the callback precondition. Already denied work is only
     * disposed: no repair, response association or event delivery is permitted.
     */
    if (READ_ONCE(ctrl->receipt_error) || READ_ONCE(ctrl->bus->rx_failed))
        goto dispose;
    if (!skb || skb_is_nonlinear(skb) ||
        !hgic_ctrl_frame_valid(skb->data, skb->len))
        goto deny;
    if (skb->data[2] != HGIC_HDR_TYPE_EVENT &&
        skb->data[2] != HGIC_HDR_TYPE_EVENT2)
        goto deny;

    /* Outer magic/length are normalized by rx.c; EVENT2 ID remains wire LE.
     * EVENT byte9 is padding, not an extended ID. No payload pointer is formed.
     */
    evt_id = skb->data[2] == HGIC_HDR_TYPE_EVENT2 ?
             get_unaligned_le16(skb->data + offsetof(struct hgic_ctrl_hdr, event2.event_id)) :
             skb->data[offsetof(struct hgic_ctrl_hdr, event.event_id)];
    if (evt_id != HGIC_EVENT_FWDBG_INFO)
        goto deny;
    goto dispose;

deny:
    /* Async denial may complete CMD waiters as ERROR, never as event success.
     * It cannot undo a prior USB resubmit or queued TX. No structured event ABI
     * is selected: even FW_INIT_DONE is unsupported in this qualification lane.
     */
    hgic_fwctrl_rx_error(ctrl);
dispose:
    if (skb)
        dev_kfree_skb(skb);
}

static int hgics_ops_start(struct ieee80211_hw *hw)
{
    int err = 0;
    struct hgics_wdev *hg = (struct hgics_wdev *)hw->priv;

    hgic_dbg("Enter ...\n");
    hg->hghw->ops->start(hw);
    hg->radio_off = 0;
    hgic_fwctrl_open_dev(&hg->ctrl, 1);
    set_bit(HGICS_STATE_START, &hg->state);
    ieee80211_wake_queues(hw);
    hgic_dbg("Leave, err:%d\r\n", err);
    return err;
}

static void hgics_ops_stop(struct ieee80211_hw *hw, bool suspend)
{
    struct hgics_wdev *hg = (struct hgics_wdev *)hw->priv;

    hgic_enter();
    hg->hghw->ops->stop(hw);
    ieee80211_stop_queues(hw);
    hgic_clear_queue(&hg->data_txq[0]);
    hgic_clear_queue(&hg->data_txq[1]);
    hgic_clear_queue(&hg->data_txq[2]);
    hgic_clear_queue(&hg->data_txq[3]);
    hgic_clear_queue(&hg->trans_q);
    hgic_clear_queue(&hg->ack_q);
#ifndef __RTOS__
    hgic_clear_queue(&hg->evt_list);
#endif
    hgic_fwctrl_close_dev(&hg->ctrl, 1);
    clear_bit(HGICS_STATE_START, &hg->state);
    hg->radio_off = 1;
    hgic_leave();
}

static int hgics_ops_add_interface(struct ieee80211_hw *hw, struct ieee80211_vif *vif)
{
    int err = 0;
    struct hgics_wdev *hg    = (struct hgics_wdev *)hw->priv;
    struct hgics_vif  *hgvif = (struct hgics_vif *)vif->drv_priv;

    hgic_dbg("add interface, type=%d\r\n", vif->type);
    switch (vif->type) {
        case NL80211_IFTYPE_STATION:
            hg->sta = hgvif;
            break;
        case NL80211_IFTYPE_AP:
            hg->ap = hgvif;
            break;
#if LINUX_VERSION_CODE > KERNEL_VERSION(3,10,0)
        case NL80211_IFTYPE_P2P_DEVICE:
            hg->p2p = hgvif;
            break;
#endif
        default:
            hgic_err("unknow interface type:%d!!\n", vif->type);
            break;
    }

    hgvif->vif  = vif;
    hgvif->hg   = hg;
    hgvif->type = vif->type;
    set_bit(HGICS_VIF_STATE_ADD, &hgvif->state);
    clear_bit(HGICS_VIF_STATE_BEACON, &hgvif->state);

#if LINUX_VERSION_CODE >= KERNEL_VERSION(3,5,0)
    vif->cab_queue = 0;
    vif->hw_queue[IEEE80211_AC_VO] = 0;
    vif->hw_queue[IEEE80211_AC_VI] = 1;
    vif->hw_queue[IEEE80211_AC_BE] = 2;
    vif->hw_queue[IEEE80211_AC_BK] = 3;
#endif

    hg->hghw->ops->add_interface(hw, vif);
    hgic_fwctrl_set_mac(&hg->ctrl, hgvif->idx, vif->addr);
    hgic_leave();
    return err;

static int hgics_ops_config(struct ieee80211_hw *hw, int radio_idx, u32 changed)
{
    int err = 0;
    u32 hw_value = 0;
    struct hgics_wdev     *hg   = (struct hgics_wdev *)hw->priv;
    struct ieee80211_conf *conf = &hw->conf;

    if (changed & IEEE80211_CONF_CHANGE_MONITOR) {
        hgic_dbg("set monitor mode is %s\r\n", (conf->flags & IEEE80211_CONF_MONITOR) ? "enable" : "disable");
        hgic_fwctrl_set_promisc(&hg->ctrl, 1, (conf->flags & IEEE80211_CONF_MONITOR) ? 1 : 0);
    }

    if (changed & IEEE80211_CONF_CHANGE_LISTEN_INTERVAL) {
        hgic_fwctrl_set_listen_interval(&hg->ctrl, 1, conf->listen_interval);
    }

    if (changed & IEEE80211_CONF_CHANGE_POWER) {
        hgic_fwctrl_set_txpower(&hg->ctrl, 1, conf->power_level);
        hg->power_level = conf->power_level;
    }

    if (changed & IEEE80211_CONF_CHANGE_CHANNEL) {
#if LINUX_VERSION_CODE >= KERNEL_VERSION(3,10,0)
        hw_value = conf->chandef.chan->center_freq;
#else
        hw_value = conf->channel->center_freq;
#endif
        hgic_fwctrl_set_center_freq(&hg->ctrl, 1, hw_value);
        hg->fw_freq = hw_value;
    }

    if (changed & IEEE80211_CONF_CHANGE_RETRY_LIMITS) {
        hgic_fwctrl_set_tx_count(&hg->ctrl, 1,
                                 conf->short_frame_max_tx_count,
                                 conf->long_frame_max_tx_count);
    }

    return err;
}

