static struct sk_buff *hgic_fwctrl_send_cmd(struct hgic_fwctrl *ctrl, u8 ifidx, u32 cmd_id, struct sk_buff *skb, struct hgic_cmd_response *resp)
{
    struct hgic_ctrl_hdr *hdr = NULL;
    u16 id = cmd_id - HGIC_CMD_START;

    /* Local station-only RAM bring-up. Explicitly exclude all maintenance,
     * testmode, OTA, save-config and unknown extended opcodes, including
     * commands reachable through the retained but unexposed iwpriv code.
     */
    switch (cmd_id) {
    case HGIC_CMD_DEV_OPEN: case HGIC_CMD_DEV_CLOSE: case HGIC_CMD_SET_MAC:
    case HGIC_CMD_SET_CENTER_FREQ: case HGIC_CMD_SET_RTS_THRESHOLD:
    case HGIC_CMD_SET_KEY: case HGIC_CMD_SET_LISTEN_INTERVAL:
    case HGIC_CMD_SET_TX_POWER: case HGIC_CMD_ADD_STA: case HGIC_CMD_REMOVE_STA:
    case HGIC_CMD_SET_AID: case HGIC_CMD_SET_TXQ_PARAM: case HGIC_CMD_GET_FW_INFO:
    case HGIC_CMD_SET_TX_LCOUNT: case HGIC_CMD_SET_TX_SCOUNT:
        break;
    default:
        dev_kfree_skb_any(skb);
        return NULL;
    }

    memset(resp, 0, sizeof(*resp));
    resp->cookie = hgic_ctrl_cookie(ctrl);
    if (resp->cookie > HGIC_TX_COOKIE_MASK || ifidx != HGIC_WDEV_ID_STA) {
        dev_kfree_skb_any(skb);
        return NULL;
    }
    hdr = (struct hgic_ctrl_hdr *)skb_push(skb, sizeof(struct hgic_ctrl_hdr));
    memset(hdr->info, 0, sizeof(hdr->info));
    hdr->hdr.magic  = cpu_to_le16(HGIC_HDR_TX_MAGIC);
    hdr->hdr.length = cpu_to_le16(skb->len);
    hdr->hdr.cookie = cpu_to_le16(resp->cookie);
    hdr->hdr.ifidx  = ifidx;
    HDR_CMDID_SET(hdr, id);
    return hgic_fwctrl_send_data(ctrl, skb, resp, HGIC_CMD_TIMEOUT);
}

int hgic_fwctrl_do_cmd(struct hgic_fwctrl *ctrl, u8 ifidx, u32 cmd_id, u8 *in, u32 in_len, u8 *out, u32 out_size)
{
    int ret = -1;
    struct sk_buff *skb  = NULL;
    struct sk_buff *resp = NULL;
    struct hgic_cmd_response receipt;
    unsigned long flags;

    if ((!in && in_len) || (!out && out_size))
        return -EINVAL;
    if(in_len > 2000){
        hgic_err("data len is too long\r\n");
        return -EINVAL;
    }

    skb = hgic_alloc_ctrl_skb(ctrl, in_len);
    if (skb) {
        if (in && in_len > 0) {
            memcpy(skb->data, in, in_len);
            skb->data[in_len] = 0;
        }

        resp = hgic_fwctrl_send_cmd(ctrl, ifidx, cmd_id, skb, &receipt);
        if (resp) {
            spin_lock_irqsave(&ctrl->lock, flags);
            if (ctrl->receipt_error)
                ret = ctrl->receipt_error;
            else
                ret = hgic_ctrl_reply_copy(resp->data, resp->len, receipt.type,
                                          receipt.ifidx, receipt.opcode, receipt.cookie,
                                          out, out_size);
            spin_unlock_irqrestore(&ctrl->lock, flags);
            dev_kfree_skb_any(resp);
        } else if (READ_ONCE(ctrl->receipt_error)) {
            ret = READ_ONCE(ctrl->receipt_error);
        }
        if (ret < 0) {
            printk("FWCTRL: cmd:%d, ret:%d (%s)\r\n", cmd_id, ret, resp ? "Responsed" : "No Response");
        }
    }
    return ret;

/* Caller holds lock. Poison all station waiters, not a later response chosen by
 * cookie alone. Boot/maintenance ownership is NOT qualified by this A1 change.
 */
static void hgic_fwctrl_bad_receipt(struct hgic_fwctrl *ctrl)
{
    struct hgic_cmd_response *resp;

    WRITE_ONCE(ctrl->receipt_error, -EPROTO);
    WRITE_ONCE(ctrl->bus->rx_failed, 1);
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if ((resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) && !resp->done) {
            resp->done = true;
            complete(&resp->cmpl);
        }
    }
}

/* USB/core ingress uses the same locked A1 waiter/copy-admission latch. */
void hgic_fwctrl_rx_error(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;

    spin_lock_irqsave(&ctrl->lock, flags);
    hgic_fwctrl_bad_receipt(ctrl);
    spin_unlock_irqrestore(&ctrl->lock, flags);
}

static int hgic_fwctrl_rx_response(struct hgic_fwctrl *ctrl, struct sk_buff *skb)
{
    int find = 0;
    unsigned long flags;
    struct hgic_cmd_response *resp = NULL;
    int status;
    u16 cookie;

    spin_lock_irqsave(&ctrl->lock, flags);
    if (!hgic_ctrl_frame_valid(skb->data, skb->len)) {
        hgic_fwctrl_bad_receipt(ctrl);
        goto unlock;
    }
    cookie = get_unaligned((const u16 *)(skb->data + 6));
    list_for_each_entry(resp, &ctrl->pd_list, list) {
        if (resp->cookie == cookie) {
            /* Duplicate/replayed completion can never replace the first skb. */
            if (resp->done)
                goto unlock;
            if (resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2) {
                if (ctrl->receipt_error ||
                    hgic_ctrl_reply_status(skb->data, skb->len, resp->type,
                                           resp->ifidx, resp->opcode, resp->cookie,
                                           &status)) {
                    hgic_fwctrl_bad_receipt(ctrl);
                    goto unlock;
                }
            }
            resp->skb = skb;
            resp->done = true;
            complete(&resp->cmpl);
            find = 1;
            break;
        }
    }
    if (!find)
        hgic_fwctrl_bad_receipt(ctrl); /* unknown/late association: no future TX */
unlock:
    spin_unlock_irqrestore(&ctrl->lock, flags);
    if (!find) {
        dev_kfree_skb_any(skb);
    }
    return 0;
}

static void hgic_fwctrl_clear_pdlist(struct hgic_fwctrl *ctrl)
{
    unsigned long flags;
    struct hgic_cmd_response *sync = NULL;

    spin_lock_irqsave(&ctrl->lock, flags);
    list_for_each_entry(sync, &ctrl->pd_list, list) {
        complete(&sync->cmpl);
    }
    spin_unlock_irqrestore(&ctrl->lock, flags);
}

static void hgic_fwctrl_work(struct work_struct *work)
{
    struct hgic_fwctrl *ctrl = NULL;
    struct sk_buff *skb = NULL;
    struct hgic_ctrl_hdr *hdr = NULL;

    ctrl = container_of(work, struct hgic_fwctrl, work);
    while (!skb_queue_empty(&ctrl->rxq)) {
        skb = skb_dequeue(&ctrl->rxq);
        if (!hgic_ctrl_frame_valid(skb->data, skb->len)) {
            hgic_fwctrl_rx_response(ctrl, skb);
            continue;
        }
        hdr = (struct hgic_ctrl_hdr *)skb->data;
        switch (hdr->hdr.type) {
            case HGIC_HDR_TYPE_CMD:
            case HGIC_HDR_TYPE_CMD2:
            case HGIC_HDR_TYPE_BOOTDL:
            case HGIC_HDR_TYPE_OTA:
                hgic_fwctrl_rx_response(ctrl, skb);
                break;
            case HGIC_HDR_TYPE_EVENT:
            case HGIC_HDR_TYPE_EVENT2:
                ctrl->rx_event(ctrl, skb);
                break;
            default:
                hgic_fwctrl_rx_response(ctrl, skb);
                break;
        }
    }
}

struct sk_buff *hgic_fwctrl_send_data(struct hgic_fwctrl *ctrl, struct sk_buff *skb, struct hgic_cmd_response *resp, u32 timeout)
{
    unsigned long flags;
    struct hgic_ctrl_hdr *hdr;

    if (skb->len < sizeof(struct hgic_ctrl_hdr) || resp->cookie > HGIC_TX_COOKIE_MASK) {
        dev_kfree_skb_any(skb);
        return NULL;
    }
    hdr = (struct hgic_ctrl_hdr *)skb->data;
    resp->type = hdr->hdr.type;
    resp->ifidx = hdr->hdr.ifidx;
    resp->opcode = HDR_CMDID(hdr);
    /* Non-CMD maintenance retains its old cookie-only response handling. It is
     * NOT station acceptance and is outside A1; do not infer a boot reply ABI.
     */

    init_completion(&resp->cmpl);
    spin_lock_irqsave(&ctrl->lock, flags);
    if (ctrl->receipt_error && (resp->type == HGIC_HDR_TYPE_CMD || resp->type == HGIC_HDR_TYPE_CMD2)) {
        spin_unlock_irqrestore(&ctrl->lock, flags);
        dev_kfree_skb_any(skb);
        return NULL;
    }
    list_add(&resp->list, &ctrl->pd_list);
    spin_unlock_irqrestore(&ctrl->lock, flags);

    if (ctrl->txq.qlen > 4) {
        kfree_skb(skb_dequeue(&ctrl->txq));
        //hgic_err("ctrl txq full, drop data (%d)\r\n", ctrl->txq.qlen);
    }

    skb_queue_tail(&ctrl->txq, skb);
    ctrl->schedule(ctrl);
    if (timeout) {
        if (!wait_for_completion_timeout(&resp->cmpl, msecs_to_jiffies(timeout))) {
            hgic_err("timeout, ctrl->rxq:%d\r\n", skb_queue_len(&ctrl->rxq));
        }
    }
    spin_lock_irqsave(&ctrl->lock, flags);
    list_del(&resp->list);
    spin_unlock_irqrestore(&ctrl->lock, flags);
#ifdef __RTOS__
    deinit_completion(&resp->cmpl);
#endif
    return resp->skb;
}

void hgic_fwctrl_rx(struct hgic_fwctrl *ctrl, u8 *data, int len)
{
    struct sk_buff *skb;
    unsigned long flags;
    if (!data || len <= 0 || len > 0xffff) {
        spin_lock_irqsave(&ctrl->lock, flags);
        hgic_fwctrl_bad_receipt(ctrl);
        spin_unlock_irqrestore(&ctrl->lock, flags);
        return;
    }
    if (ctrl->wq) {
        skb = dev_alloc_skb(len);
        if (skb) {
            memcpy(skb->data, data, len);
            skb_put(skb, len);
            skb_queue_tail(&ctrl->rxq, skb);
            queue_work(ctrl->wq, &ctrl->work);
        } else {
            hgic_err("alloc skb fail\r\n");
        }
    } else {
        hgic_err("fwctrl workqueue is NULL\r\n");
    }
}

void hgic_fwctrl_init(struct hgic_fwctrl *ctrl, void *dev, struct hgic_bus *bus)
{
    memset(ctrl, 0, sizeof(struct hgic_fwctrl));
    ctrl->dev = dev;
    ctrl->bus = bus;
    ctrl->radio_onoff = 1;
    spin_lock_init(&ctrl->lock);
    INIT_LIST_HEAD(&ctrl->pd_list);
    skb_queue_head_init(&ctrl->rxq);
    skb_queue_head_init(&ctrl->txq);
    INIT_WORK(&ctrl->work, hgic_fwctrl_work);
    ctrl->wq = ALLOC_ORDERED_WORKQUEUE("fwctrl", 0);
}

void hgic_fwctrl_release(struct hgic_fwctrl *ctrl)
{
    cancel_work_sync(&ctrl->work);
    hgic_fwctrl_clear_pdlist(ctrl);
    hgic_clear_queue(&ctrl->txq);
    hgic_clear_queue(&ctrl->rxq);
#ifdef __RTOS__
    skb_queue_head_deinit(&ctrl->rxq);
    skb_queue_head_deinit(&ctrl->txq);
    spin_lock_deinit(&ctrl->lock);
#endif
    if (ctrl->wq) {
        flush_workqueue(ctrl->wq);
        destroy_workqueue(ctrl->wq);
    }
}

int hgic_fwctrl_get_fwinfo(struct hgic_fwctrl *ctrl, u8 ifidx, struct hgic_fw_info *info)
{
    int ret = 0;
    u8 retail[24] = {0};
    struct hgic_fw_info decoded = {0};
    if (!info)
        return -EINVAL;
    /* Exact owned firmware2.1.0.1/stock REA layout, directly observed24
     * bytes. The newer mirror's app_version extends its C structure to28;
     * never substitute that host structure as the retail wire ABI.
     */
    ret = hgic_fwctrl_get_bytes(ctrl, ifidx, HGIC_CMD_GET_FW_INFO, retail, sizeof(retail));
    if (ret == sizeof(retail)) {
        if (!hgic_ctrl_retail_info_valid(retail, sizeof(retail)))
            return -EPROTO;
        decoded.version = get_unaligned_le32(retail);
        decoded.svn_version = get_unaligned_le32(retail + 4);
        decoded.chip_id = get_unaligned_le16(retail + 8);
        decoded.cpu_id = get_unaligned_le16(retail + 10);
        memcpy(decoded.mac, retail + 12, 6);
        decoded.smt_dat = get_unaligned_le32(retail + 20);
        *info = decoded; /* no partial output or default-MAC fallback on reject */
    }
    return ret;
}

//command response
struct hgic_cmd_response {
    struct list_head list;
    unsigned short cookie;
    unsigned short opcode;
    unsigned char type;
    unsigned char ifidx;
    bool done; /* first response wins, including a signed firmware error */
    struct completion cmpl;
    struct sk_buff   *skb;
};

struct hgic_fwctrl {
    struct device      *dev;
    u16                 cookie;
    int                 receipt_error; /* inhibits subsequent station admission */
    spinlock_t          lock;    /*ctrl packet pending lock*/
    struct list_head    pd_list; /*ctrl packet pending queue (for sync cmd)*/
    struct sk_buff_head rxq;   /*fw ctrl packet rx queue*/
    struct sk_buff_head txq;   /*fw ctrl packet tx queue*/
    struct work_struct  work;  /*fw ctrl rx packet process work*/
    struct workqueue_struct *wq;
    u8                  qc_mode;
    u8                  radio_onoff;
    struct hgic_fw_info *fwinfo;
    struct hgic_bus *bus;
    void (*schedule)(struct hgic_fwctrl *ctrl);
    void (*rx_event)(struct hgic_fwctrl *ctrl, struct sk_buff *skb);
};

