    hdr->magic  = cpu_to_le16(HGIC_HDR_TX_MAGIC);
    hdr->length = cpu_to_le16(skb->len);
    hdr->cookie = cpu_to_le16(resp.cookie);
    hdr->type   = HGIC_HDR_TYPE_OTA;
    hdr->ifidx  = HGIC_WDEV_ID_STA;
    hgic_fwctrl_send_data(ota->ctrl, skb, &resp, tmo);
