static int hgics_fwevent_open(struct inode *inode, struct file *file)
{
    return single_open(file, NULL, PDE_DATA(inode));
}
static ssize_t hgics_fwevent_read(struct file *file, char __user *buffer,
                                  size_t count, loff_t *data)
{
    int ret = 0;
    struct sk_buff *skb = NULL;
    struct seq_file   *seq = (struct seq_file *)file->private_data;
    struct hgics_wdev *hg  = (struct hgics_wdev *)seq->private;

    if (down_timeout(&hg->evt_sema, msecs_to_jiffies(100))) {
        return 0;
    }

    if (!skb_queue_empty(&hg->evt_list)) {
        skb = skb_dequeue(&hg->evt_list);
        if (skb) {
            if (!copy_to_user(buffer, skb->data, skb->len)) {
                ret = skb->len;
            }
            kfree_skb(skb);
        }
    }
    return ret;
}
static const struct proc_ops hgics_pops_fwevent = {
    .proc_open = hgics_fwevent_open,
    .proc_read = hgics_fwevent_read,
    .proc_lseek = seq_lseek,
    .proc_release = single_release,
};

void hgics_create_common_procfs(struct hgics_wdev *hg)
{
    hg->proc.status = proc_create_data("status", 0x0444,
                                       hg->proc.rootdir, &hgics_pops_status, hg);
    if (hg->proc.status == NULL) {
        hgic_err("create proc file: status failed\r\n");
    }
    hg->proc.fwevnt = proc_create_data("fwevnt", 0x0444,
                                       hg->proc.rootdir, &hgics_pops_fwevent, hg);
    if (hg->proc.fwevnt == NULL) {
        hgic_err("create proc file: fwevt failed\r\n");
    }
    /* No writable private maintenance interface in the RAM-only port. */
    hg->proc.iwpriv = NULL;
}

void hgics_delete_common_procfs(struct hgics_wdev *hg)
{
    if (hg->proc.status) {
        remove_proc_entry("status", hg->proc.rootdir);
        hg->proc.status = NULL;
    }
    if (hg->proc.fwevnt) {
        remove_proc_entry("fwevnt", hg->proc.rootdir);
        hg->proc.fwevnt = NULL;
    }
    if (hg->proc.iwpriv) {
        remove_proc_entry("iwpriv", hg->proc.rootdir);
        hg->proc.iwpriv = NULL;
    }
}

void hgics_create_procfs(struct hgics_wdev *hg)
{
    hgic_dbg("enter\r\n");
    hg->proc.rootdir = proc_mkdir("hgics", NULL);
    if (hg->proc.rootdir == NULL) {
        hgic_err("create proc dir: hgic failed\r\n");
        return;
    }
    hgics_create_common_procfs(hg);
    hg->hghw->ops->create_procfs(hg);
    hgic_dbg("leave\r\n");
}

void hgics_delete_procfs(struct hgics_wdev *hg)
{
    hgic_dbg("enter\r\n");
    if (hg->proc.rootdir) {
        hgics_delete_common_procfs(hg);
        hg->hghw->ops->delete_procfs(hg);
        remove_proc_entry("hgics", NULL);
        hg->proc.rootdir = NULL;
    }
    hgic_dbg("leave\r\n");
}

static int hgics_bgnops_init(struct hgics_wdev *hg)
{
    static const u32 initial_cipher_profile[] = { WLAN_CIPHER_SUITE_CCMP };
    int i = 0;
    struct ieee80211_hw *hw = hg->hw;
    struct ieee80211_supported_band *sband = &hg->sbands[IEEE80211_BAND_2GHZ];

    hgic_dbg("Enter\n");
#if LINUX_VERSION_CODE < KERNEL_VERSION(3,14,0)
    hw->channel_change_time = 1;
#endif
    hw->queues = 5;
#if LINUX_VERSION_CODE >= KERNEL_VERSION(3,5,0)
    hw->offchannel_tx_hw_queue = 4;
#endif

    hw->wiphy->interface_modes = BIT(NL80211_IFTYPE_STATION) /*|
                                 BIT(NL80211_IFTYPE_P2P_CLIENT) |
                                 BIT(NL80211_IFTYPE_P2P_GO) |
                                 BIT(NL80211_IFTYPE_P2P_DEVICE)*/
                                 ;

#if LINUX_VERSION_CODE >= KERNEL_VERSION(4,2,0)
    ieee80211_hw_set(hw, SIGNAL_DBM);
    ieee80211_hw_set(hw, AMPDU_AGGREGATION);
    ieee80211_hw_set(hw, TX_AMPDU_SETUP_IN_HW);
    ieee80211_hw_set(hw, QUEUE_CONTROL);
    ieee80211_hw_set(hw, HAS_RATE_CONTROL);
    /* Initial qualification is WPA2/CCMP without PMF; do not advertise
     * unqualified extended management-key/cipher firmware semantics.
     */
    hw->wiphy->cipher_suites = initial_cipher_profile;
    hw->wiphy->n_cipher_suites = ARRAY_SIZE(initial_cipher_profile);
#else
    hw->flags = IEEE80211_HW_SIGNAL_DBM |
                IEEE80211_HW_AMPDU_AGGREGATION | 
                IEEE80211_HW_MFP_CAPABLE |
#if LINUX_VERSION_CODE >= KERNEL_VERSION(3,2,0)
                IEEE80211_HW_TX_AMPDU_SETUP_IN_HW |
#endif
#if LINUX_VERSION_CODE >= KERNEL_VERSION(3,5,0)
#endif
                IEEE80211_HW_HAS_RATE_CONTROL;
#endif

    memcpy(sband, &hgics_band_2G, sizeof(struct ieee80211_supported_band));
    hw->wiphy->bands[IEEE80211_BAND_2GHZ] = sband;
    /* One station only: no multi-interface/AP combination is advertised.
     * cfg80211 rejects combinations containing unsupported iftypes and
     * single-interface non-DFS combinations are implicit, not listed.
     */
    hw->wiphy->iface_combinations = NULL;
    hw->wiphy->n_iface_combinations = 0;
#if LINUX_VERSION_CODE > KERNEL_VERSION(3,10,0)
    hw->wiphy->flags |= WIPHY_FLAG_HAS_REMAIN_ON_CHANNEL;
#endif
    hw->vif_data_size = sizeof(struct hgics_vif);
#if LINUX_VERSION_CODE >= KERNEL_VERSION(3,8,0)
    hw->chanctx_data_size = sizeof(struct hgics_chanctx_priv);
#endif
    hw->max_rates = 4;
    hw->max_rate_tries = 11;
    hw->max_rx_aggregation_subframes = 8;
    hw->max_tx_aggregation_subframes = 64;

    for (i = 0; i < 4; i++) {
        memcpy(hg->macaddr[i].addr, hg->fwinfo.mac, 6);
        hg->macaddr[i].addr[5] += i;
    }
    hw->wiphy->n_addresses = 1;

#ifdef CONFIG_BT
    if (hg->bt_en && hg->dev_id == HGIC_WLAN_8400) {
        hg->hci = hci_alloc_dev();
        hgic_dbg("bluetooth enabled\r\n");
    }
#endif

    hgic_dbg("Leave\n");
    return 0;

